p=pd.read_csv(O/'results/bulk_validation/all_gene_paired_differences.tsv.gz',sep='\t',index_col=0);d2=p.loc['CGNL1'];print('RNA18',int((d2>0).sum()),int((d2<0).sum()),'LOO',min(d2.drop(i).mean() for i in d2.index),max(d2.drop(i).mean() for i in d2.index));print('CANDIDATE_CNVS',pd.read_csv(O/'results/cnv/candidate_CNV_summary.tsv',sep='\t').query("gene=='CGNL1'").to_string(index=False));
